<?php defined('BASEPATH') or exit('No direct script access allowed'); $this->load->model('goals/goals_model'); ?><?php $rows=$this->goals_model->get_monthly_completion(); ?>
<div class="widget" id="widget-<?php echo create_widget_id('goals-monthly'); ?>"><div class="panel_s"><div class="panel-body"><div class="widget-dragger"></div><h4><?php echo _l('goals_monthly_completion'); ?></h4><canvas id="goals-monthly-widget-chart" height="180"></canvas></div></div></div><script>$(function(){new Chart(document.getElementById('goals-monthly-widget-chart'),{type:'line',data:{labels:<?php echo json_encode(array_column($rows,'month')); ?>,datasets:[{data:<?php echo json_encode(array_map('intval',array_column($rows,'total'))); ?>,tension:.35,fill:true}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}}}});});</script>